    if (!ADMIN) return;
    status("Saving…");
    try {
      const response = await fetch("/__viewer_admin/annotations", {
        method: "POST", headers: { "Content-Type": "application/json", "X-Viewer-Admin-Token": ADMIN_TOKEN }, body: JSON.stringify(data, null, 2)
