{"path":"/GitHub/link_6a1a5af1b40c8191affccbb98ac60fa3/create_file","args":{"repository_full_name":"Satobloc/HsH","path":"CONVERSATION_VIEWER/argus_followup.css","message":"Style Viewer click-open and internal quick controls","content":".message.provenance-collapsed:not(.annotation-open) {
