      if (selectedProvenance() === "all") return;
      event.preventDefault();
      event.stopImmediatePropagation();
      cycleProvenance(-1);
    }, true);

    next?.addEventListener("click", event => {
      if (selectedProvenance() === "all") return;
      event.preventDefault();
      event.stopImmediatePropagation();
      cycleProvenance(1);
    }, true);
  }

