 if not p.exists():return {}
 try:rows=json.loads(p.read_text(encoding="utf-8")).get("conversations",[])
 except:return {}
 out={}
 for c in rows:
  for k in ("path","source_path"):
   if c.get(k):out[str(c[k]).replace("\\","/")]=c
