 fmap={"author":rec.speaker or rec.role,"speaker":rec.speaker,"role":rec.role,"title":rec.title,
       "conversation":rec.conversation_id,"cid":rec.conversation_id,"date":rec.timestamp[:10],"status":" ".join(status(rec.text))}
